INSERT INTO `questions` (`id`, `text`, `content`, `active`, `order_index`) VALUES
(2,
'02 — O AUTOR DO APP, MISTER GANDHI, AFIRMA QUE A "LEI DA PENA DE MORTE" JÁ ESTÁ INSTAURADA NO BRASIL. SEGUNDO ELE, ELA É SANCIONADA PELA CONSTITUIÇÃO (ART. 228: OS MENORES DE 18 ANOS SÃO PENALMENTE INIMPUTÁVEIS), RATIFICADA PELO CONGRESSO ATRAVÉS DO ART. 27 DO CÓDIGO PENAL, PELO ART. 104 DO ECA (ESTATUTO DA CRIANÇA E DO ADOLESCENTE) E HOMOLOGADA PELO STF, SENDO CONSIDERADA APENAS UM "ATO INFRACIONAL". NA VERDADE, O QUE ESTES ARTIGOS DIZEM É QUE OS MENORES DE 18 ANOS PODEM FAZER TUDO, INCLUSIVE MATAR. VOCÊ ACHA QUE ELE ESTÁ CERTO?',
'[{"bold":true,"text":"02 — O AUTOR DO APP, MISTER GANDHI, AFIRMA QUE A ","color":"#0000FF"},{"bold":true,"text":"\\"LEI DA PENA DE MORTE\\" JÁ ESTÁ INSTAURADA NO BRASIL","color":"#FF0000"},{"bold":true,"text":". SEGUNDO ELE, ELA É SANCIONADA PELA CONSTITUIÇÃO, RATIFICADA PELO CONGRESSO E HOMOLOGADA PELO STF. VOCÊ ACHA QUE ELE ESTÁ CERTO?","color":"#008000"}]',
1,2);

INSERT INTO `questions` (`id`, `text`, `content`, `active`, `order_index`) VALUES
(3,
'03 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA FEMINICIDA (ASSASSINO DE MULHER: ESPOSA, NAMORADA, ETC.) E DE QUE OS SEUS BENS SEJAM ESPOLIADOS PARA RESSARCIR OS FAMILIARES DA VÍTIMA? CERCA DE 10 MULHERES SÃO ASSASSINADAS TODOS OS DIAS NO BRASIL. A "LEI MARIA DA PENHA" SÓ DIMINUIU EM 10% O FEMINICÍDIO NO PAÍS.',
'[{"bold":true,"text":"03 — VOCÊ É A FAVOR DA ","color":"#0000FF"},{"bold":true,"text":"\\"PENA DE MORTE\\" PARA FEMINICIDA","color":"#FF0000"},{"bold":true,"text":" E DE QUE OS SEUS BENS SEJAM ESPOLIADOS PARA RESSARCIR OS FAMILIARES DA VÍTIMA? CERCA DE 10 MULHERES SÃO ASSASSINADAS TODOS OS DIAS NO BRASIL.","color":"#008000"}]',
