INSERT INTO `questions` (`id`, `text`, `content`, `active`, `order_index`) VALUES
(4,
'04 — TALVEZ VOCÊ NÃO SEJA A FAVOR DA "PENA DE MORTE" PARA FEMINICIDAS, MAS VOCÊ CONCORDA COM A "LEI GANDHI ANTI-FEMINICÍDIO" NOS SEGUINTES MOLDES? UMA LEI DE PROTEÇÃO À VIDA E À INTEGRIDADE FÍSICA DA MULHER, BASEADA NA "LEI DA IGUALITARIEDADE DE DIREITOS" E NA "LEI DA JUSTA RECOMPENSA". SE ALGUÉM A AGREDIR, FERIR, MUTILAR, INCENDIAR OU CAUSAR-LHE MALES E DEFORMAÇÕES FÍSICAS, QUE SEJA FEITO O MESMO AO AGRESSOR, NA MESMA PROPORÇÃO. ALÉM DISSO, APLICAR-SE-IA A PENA DE PRISÃO PREVISTA EM LEI COM CUMPRIMENTO INTEGRAL, A ESPOLIAÇÃO DE SEUS BENS PARA INDENIZAR A VÍTIMA E, CASO SEJA NECESSÁRIO O TRANSPLANTE DE ALGUM ÓRGÃO (RINS, PULMÃO, ETC.), O AGRESSOR SERIA UM DOADOR COMPULSÓRIO. SE O ÓRGÃO NÃO FOR COMPATÍVEL COM A VÍTIMA, SERÁ DOADO AO SUS, COLOCANDO A VÍTIMA COMO O PRIMEIRO PACIENTE NA FILA DE ESPERA DE TRANSPLANTE. SIM OU NÃO? (NOTA: CERCA DE 21 MILHÕES DE MULHERES FORAM AGREDIDAS E ESPANCADAS EM 2017 NO BRASIL).',
'[{"bold":true,"text":"04 — TALVEZ VOCÊ NÃO SEJA A FAVOR DA ","color":"#0000FF"},{"bold":true,"text":"\\"LEI GANDHI ANTI-FEMINICÍDIO\\"","color":"#FF0000"},{"bold":true,"text":" NOS SEGUINTES MOLDES? UMA LEI DE PROTEÇÃO À VIDA E À INTEGRIDADE FÍSICA DA MULHER. ","color":"#0000FF"},{"bold":true,"text":"SIM OU NÃO?","color":"#FF0000"},{"bold":true,"text":" (NOTA: CERCA DE 21 MILHÕES DE MULHERES FORAM AGREDIDAS E ESPANCADAS EM 2017 NO BRASIL).","color":"#008000"}]',
1,4);

INSERT INTO `questions` (`id`, `text`, `content`, `active`, `order_index`) VALUES
(5,
'05 — EXISTE JUSTIÇA PARA ASSASSINOS NO BRASIL? SIM OU NÃO? JUSTIÇA É A IGUALDADE DE DIREITO ONDE A PENA É IGUAL AO DELITO; CASO HAJA DESIGUALDADE ENTRE AMBOS, HOUVE INJUSTIÇA. SE A PENA É MAIOR QUE O DELITO, SOMOS INJUSTOS COM O AGRESSOR; SE A PENA É MENOR QUE O DELITO, SOMOS INJUSTOS COM A VÍTIMA.',
'[{"bold":true,"text":"05 — EXISTE JUSTIÇA PARA ASSASSINOS NO BRASIL? ","color":"#0000FF"},{"bold":true,"text":"SIM OU NÃO?","color":"#FF0000"},{"bold":true,"text":" JUSTIÇA É A IGUALDADE DE DIREITO ONDE A PENA É IGUAL AO DELITO; CASO HAJA DESIGUALDADE ENTRE AMBOS, HOUVE INJUSTIÇA.","color":"#008000"}]',
1,5);

INSERT INTO `questions` (`id`, `text`, `content`, `active`, `order_index`) VALUES
(6,
'06 — UM BANDIDO MATA TODA UMA FAMÍLIA, GANHA 30 ANOS DE PRISÃO E SAI APÓS CUMPRIR 1/3 DELA (DEZ ANOS). HOUVE UMA JUSTIÇA PLENA E JUSTA? AQUELAS VIDAS SÓ VALEM DEZ ANOS DE PRISÃO DA VIDA DO ASSASSINO? O DIREITO DO ASSASSINO É MAIOR QUE O DA VÍTIMA? O ASSASSINO É CIDADÃO DE 1ª CLASSE E A VÍTIMA É CIDADÃO DE 2ª? UM É FILHO DE DEUS E O OUTRO É ENTEADO OU FILHO DO DIABO? O ART. 5º DA CONSTITUIÇÃO DIZ: "TODOS SÃO IGUAIS PERANTE A LEI, SEM DISTINÇÃO DE QUALQUER NATUREZA..."',
'[{"bold":true,"text":"06 — UM BANDIDO MATA TODA UMA FAMÍLIA, GANHA 30 ANOS DE PRISÃO E SAI APÓS CUMPRIR 1/3 DELA (DEZ ANOS). ","color":"#0000FF"},{"bold":true,"text":"HOUVE UMA JUSTIÇA PLENA E JUSTA?","color":"#FF0000"},{"bold":true,"text":" O ART. 5º DA CONSTITUIÇÃO DIZ: \\"TODOS SÃO IGUAIS PERANTE A LEI, SEM DISTINÇÃO DE QUALQUER NATUREZA...\\"","color":"#008000"}]',
1,6);

