INSERT INTO `questions` (`id`, `text`, `content`, `active`, `order_index`) VALUES
(10,
'10 — VOCÊ É A FAVOR DA “PENA DE MORTE” PARA POLÍTICOS OU FUNCIONÁRIOS PÚBLICOS (CIVIS OU MILITARES) QUE DESVIAM DINHEIRO PÚBLICO (PECULATO)? ESSE É UM CRIME CONTRA O POVO E DEVE SER CONSIDERADO (GENOCÍDIO), E OS BENS DOS CULPADOS SERIAM ESPOLIADOS PARA RESSARCIR O ESTADO BRASILEIRO. MAIS DE 153.000 DOENTES MORREM TODOS OS ANOS NO SUS POR FALTA DE MÉDICOS, EM CONSEQUÊNCIA DOS MAIS DE 300 BILHÕES DE REAIS QUE SÃO DESVIADOS ANUALMENTE.',
