INSERT INTO `questions` (`id`, `text`, `content`, `active`, `order_index`) VALUES
(12,
'12 — VOCÊ É A FAVOR DA "LEI GANDHI ANTI-AUMENTO SALARIAL DOS POLÍTICOS"? ELA PROIBIRIA OS PARLAMENTARES DE VOTAREM EM PROJETOS DE LEI QUE VISEM AUMENTAR SEUS PRÓPRIOS SALÁRIOS. ISSO PASSARIA A SER FEITO POR COMISSÕES INDEPENDENTES E SANCIONADO PELO PRESIDENTE DA REPÚBLICA OU PELO STF, DE ACORDO COM O PERCENTUAL DA INFLAÇÃO, COMO OCORRE COM QUALQUER TRABALHADOR BRASILEIRO.',
'[{"bold":true,"text":"12 — VOCÊ É A FAVOR DA ","color":"#0000FF"},{"bold":true,"text":"\\"LEI GANDHI ANTI-AUMENTO SALARIAL DOS POLÍTICOS\\"","color":"#FF0000"},{"bold":true,"text":"? ISSO PASSARIA A SER FEITO POR COMISSÕES INDEPENDENTES E SANCIONADO PELO PRESIDENTE DA REPÚBLICA OU PELO STF.","color":"#008000"}]',
