INSERT INTO `questions` (`id`, `text`, `content`, `active`, `order_index`) VALUES
(13,
'13 — VOCÊ É A FAVOR DA "LEI GANDHI DE PROTEÇÃO À VÍTIMA DE RAPTO"? ELA OBRIGARIA O RAPTOR, SOB PENA DE CHICOTADAS, A CONFESSAR ONDE ESCONDEU A VÍTIMA POUCAS HORAS ANTES DE SUA PRISÃO (APENAS EM CASOS DE RAPTO RECENTE E IMEDIATO, ONDE HAJA A POSSIBILIDADE DE A VÍTIMA AINDA ESTAR VIVA). O ARTIGO 5º, INCISO III DA CONSTITUIÇÃO, QUE DIZ: "NINGUÉM SERÁ SUBMETIDO A TORTURA NEM A TRATAMENTO DESUMANO OU DEGRADANTE", SÓ PROTEGE O BANDIDO?',
'[{"bold":true,"text":"13 — VOCÊ É A FAVOR DA ","color":"#0000FF"},{"bold":true,"text":"\\"LEI GANDHI DE PROTEÇÃO À VÍTIMA DE RAPTO\\"","color":"#FF0000"},{"bold":true,"text":"? O ARTIGO 5º, INCISO III DA CONSTITUIÇÃO, DIZ: \\"NINGUÉM SERÁ SUBMETIDO A TORTURA NEM A TRATAMENTO DESUMANO OU DEGRADANTE\\".","color":"#008000"}]',
1,13);

INSERT INTO `questions` (`id`, `text`, `content`, `active`, `order_index`) VALUES
(14,
'14 — VOCÊ CONCORDA COM A "LEI GANDHI DE PROTEÇÃO À SAÚDE, À EDUCAÇÃO E À PESQUISA"? ELA PROPÕE QUE A VERBA DESTINADA A ESSAS ÁREAS SEJA SEMPRE AUMENTADA PERCENTUALMENTE NO MÍNIMO IGUAL OU ACIMA DA INFLAÇÃO, JAMAIS PODENDO SER DIMINUÍDA. ALÉM DISSO, PROPÕE UMA EMENDA CONSTITUCIONAL PARA TRANSFORMAR A REFERIDA LEI EM "CLÁUSULA PÉTREA" (OU SEJA, IMUTÁVEL). ATUALMENTE, QUANDO O GOVERNO PRECISA DE MAIS DINHEIRO, SEMPRE O RETIRA DA SAÚDE, DA EDUCAÇÃO E DA PESQUISA CIENTÍFICA.',
'[{"bold":true,"text":"14 — VOCÊ CONCORDA COM A ","color":"#0000FF"},{"bold":true,"text":"\\"LEI GANDHI DE PROTEÇÃO À SAÚDE, À EDUCAÇÃO E À PESQUISA\\"","color":"#FF0000"},{"bold":true,"text":"? ELA PROPÕE QUE A VERBA DESTINADA A ESSAS ÁREAS SEJA SEMPRE AUMENTADA NO MÍNIMO IGUAL OU ACIMA DA INFLAÇÃO.","color":"#008000"}]',
1,14);

INSERT INTO `questions` (`id`, `text`, `content`, `active`, `order_index`) VALUES
