'[{"bold":true,"text":"15 — VOCÊ É A FAVOR DA ","color":"#0000FF"},{"bold":true,"text":"“PENA DE MORTE” PARA ASSASSINOS MENORES DE 18 ANOS","color":"#FF0000"},{"bold":true,"text":"? A LEI DA INIMPUTABILIDADE PARA MENORES DE 18 ANOS É APRESENTADA AQUI COMO INCONSTITUCIONAL.","color":"#008000"}]',
1,15);

