INSERT INTO `questions` (`id`, `text`, `content`, `active`, `order_index`) VALUES
(20,
'20 — CASO NÃO SEJA A FAVOR DA "PENA DE MORTE", VOCÊ É A FAVOR DA "LEI GANDHI ANTI-HOMICÍDIO"? ELA PROPÕE QUE O CRIME DE HOMICÍDIO SEJA IMPRESCRITÍVEL, INAFIANÇÁVEL E COM CUMPRIMENTO INTEGRAL DA PENA NOS SEGUINTES MOLDES: SE ALGUÉM AGREDIR UMA PESSOA HUMANA — FERINDO-A, MUTILANDO-A, INCENDIANDO-A OU CAUSANDO-LHE MALES E DEFORMAÇÕES FÍSICAS —, QUE SEJA FEITO O MESMO AO AGRESSOR, NA MESMA PROPORÇÃO. SOMA-SE A ISSO A PENA DE PRISÃO PREVISTA EM LEI COM CUMPRIMENTO INTEGRAL, A ESPOLIAÇÃO DE SEUS BENS PARA INDENIZAÇÃO À VÍTIMA E, CASO SEJA NECESSÁRIO O TRANSPLANTE DE ALGUM ÓRGÃO (RINS, PULMÃO, ETC.), O AGRESSOR SERIA UM DOADOR COMPULSÓRIO. SE O ÓRGÃO NÃO FOR COMPATÍVEL, SERIA DOADO AO SUS, COLOCANDO A VÍTIMA COMO O PRIMEIRO PACIENTE NA FILA DE ESPERA. ATUALMENTE, O HOMICÍDIO PRESCREVE EM 20 ANOS (ART. 109 DO CÓDIGO PENAL), MAS O MORTO PERMANECE MORTO (A MORTE NÃO PRESCREVE). (NOTA: AJUSTEI O ARTIGO CITADO DE 21 PARA 109, QUE É O QUE REGE A PRESCRIÇÃO NO CÓDIGO PENAL BRASILEIRO).',
'[{"bold":true,"text":"20 — CASO NÃO SEJA A FAVOR DA ","color":"#0000FF"},{"bold":true,"text":"\\"LEI GANDHI ANTI-HOMICÍDIO\\"","color":"#FF0000"},{"bold":true,"text":"? ATUALMENTE, O HOMICÍDIO PRESCREVE EM 20 ANOS (ART. 109 DO CÓDIGO PENAL), MAS O MORTO PERMANECE MORTO.","color":"#008000"}]',
1,20);

