INSERT INTO `questions` (`id`, `text`, `content`, `active`, `order_index`) VALUES
(39,
'39 — VOCÊ ACHA QUE O BRASIL TEM UMA DEMOCRACIA PLENA, AMPLA E IRRESTRITA? NO PASSADO, O MILITAR APOSENTAVA-SE COM O SOLDO ACIMA DO RECEBIDO QUANDO ESTAVA NA ATIVA. QUANDO UM JUIZ COMETE UM CRIME, ELE É APENAS EXONERADO DO CARGO E APOSENTADO — OU MELHOR, PREMIADO, POIS VAI RECEBER SEM TRABALHAR. O MILITAR APOSENTADO, OUTRORA, AO MORRER DEIXAVA A APOSENTADORIA PARA A ESPOSA, E A ESPOSA DEIXAVA PARA OS FILHOS PERPETUAMENTE. E TODOS SOMOS IGUAIS PERANTE A CONSTITUIÇÃO (ART. 5º DA CONST. FEDERAL). MAS ALGUNS SÃO MAIS IGUAIS QUE OUTROS.',
'[{"bold":true,"text":"39 — VOCÊ ACHA QUE O BRASIL TEM UMA ","color":"#0000FF"},{"bold":true,"text":"DEMOCRACIA PLENA, AMPLA E IRRESTRITA","color":"#FF0000"},{"bold":true,"text":"? TODOS SOMOS IGUAIS PERANTE A CONSTITUIÇÃO, MAS ALGUNS SÃO MAIS IGUAIS QUE OUTROS.","color":"#008000"}]',
1,39);

